@startuml

class Customer {
  + Name : string
  + Surname : string
  + Email : string
  + Telephone : string
  + HomeAddress : string
}

class Dish {
  + Name : string
  + PreparationTime : int
}

class Order {
  + TotalCost : float
  + EstimatedDeliveryTime : time
  + Status : string
}

class Payment {
  + PaymentMethod : string
  + IsSuccessful : boolean
}

class Kitchen {
  + Workload : int
}

class Delivery {
  + Status : string
}

Customer "1" -- "*" Order : places
Order "*" -- "1..*" Dish : contains
Order "1" -- "1" Payment : processed by
Order "1" -- "1" Kitchen : sent to
Order "1" -- "1" Delivery : fulfilled by

@enduml

